/**
 * Copy-able code snippet with minimal TypeScript token colouring.
 *
 * The highlighter is deliberately small: snippets are generated by
 * `renderCall`, so the grammar is limited to strings, numbers, keywords,
 * comments and identifiers followed by `(`.
 */
import { useCallback, useEffect, useState } from 'react';
import { Check, Copy } from 'lucide-react';
import { cn } from '../lib/cn';

interface Props {
    code: string;
    className?: string;
}

const TOKEN_PATTERN =
    /(\/\/[^\n]*|'(?:\\.|[^'\\])*'|`(?:\\.|[^`\\])*`|\b(?:const|let|import|from|new|return|true|false|null|undefined|await|async)\b|\b-?\d+(?:\.\d+)?\b|[A-Za-z_$][\w$]*(?=\())/g;

export function CodeBlock({ code, className }: Props) {
    const [copied, setCopied] = useState(false);

    useEffect(() => {
        if (!copied) {
            return;
        }
        const timer = window.setTimeout(() => setCopied(false), 1400);
        return () => window.clearTimeout(timer);
    }, [copied]);

    const copy = useCallback(() => {
        void navigator.clipboard?.writeText(code).then(() => setCopied(true));
    }, [code]);

    return (
        <div
            className={cn(
                'group relative rounded-md border border-border bg-muted/40 dark:bg-black/30',
                className
            )}
        >
            <button
                type="button"
                onClick={copy}
                aria-label={copied ? 'Copied' : 'Copy code'}
                className="absolute right-1.5 top-1.5 flex h-6 w-6 items-center justify-center rounded text-muted-foreground opacity-0 transition-opacity hover:bg-background hover:text-foreground focus:opacity-100 group-hover:opacity-100"
            >
                {copied ? <Check className="h-3 w-3 text-success" /> : <Copy className="h-3 w-3" />}
            </button>
            <pre className="scrollbar-thin overflow-x-auto px-3 py-2.5 pr-9 font-mono text-xs leading-relaxed">
                <code>
                    {code.split(TOKEN_PATTERN).map((token, i) => (
                        <span key={i} className={tokenClass(token)}>
                            {token}
                        </span>
                    ))}
                </code>
            </pre>
        </div>
    );
}

function tokenClass(token: string): string {
    if (!token) {
        return '';
    }
    if (token.startsWith('//')) {
        return 'text-muted-foreground italic';
    }
    if (token.startsWith("'") || token.startsWith('`')) {
        return 'text-success';
    }
    if (/^(const|let|import|from|new|return|await|async)$/.test(token)) {
        return 'text-primary font-medium';
    }
    if (/^(true|false|null|undefined)$/.test(token)) {
        return 'text-warning';
    }
    if (/^-?\d/.test(token)) {
        return 'text-warning';
    }
    if (/^[A-Za-z_$][\w$]*$/.test(token)) {
        return 'text-foreground font-medium';
    }
    return 'text-muted-foreground';
}
